solutions.naive:
class Solution:
    def longestConsecutive(self, nums: list[int]) -> int:
        best = 0
        for x in nums:
            cur, length = x, 1
            while cur + 1 in nums:
                cur += 1
                length += 1
            best = max(best, length)
        return best

solutions.better:
class Solution:
    def longestConsecutive(self, nums: list[int]) -> int:
        if not nums:
            return 0
        vals = sorted(set(nums))
        best = length = 1
        for i in range(1, len(vals)):
            if vals[i] == vals[i-1] + 1:
                length += 1
            else:
                length = 1
            best = max(best, length)
        return best

