class Solution:
    def longestConsecutive(self, nums: list[int]) -> int:
        vals = set(nums)
        best = 0
        for x in vals:
            if x - 1 in vals:
                continue
            y = x
            while y + 1 in vals:
                y += 1
            best = max(best, y - x + 1)
        return best

